import java.util.LinkedList;

class Bucket {
    private LinkedList<Bucket> list;
    private Bucket previous;
    private Bucket next;

    public Bucket(LinkedList<Bucket> list) {
        this.list = list;
    }

    /** 
     * Inserts this bucket in the data structure before the  {@code bucket}.
     * @param bucket the bucket, that will be the next to this bucket.
     */
    void insertBefore(Bucket bucket) {
        if (bucket == null) {
            throw new IllegalArgumentException("Bucket cannot be null");
        }
        if (this.list == null || bucket.list != this.list) {
            throw new IllegalStateException("Buckets are not in the same list");
        }

        this.next = bucket;
        this.previous = bucket.previous;
        if (bucket.previous != null) {
            bucket.previous.next = this;
        }
        bucket.previous = this;

        if (bucket == list.getFirst()) {
            list.addFirst(this);
        }
    }
}
