public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    Vec2 position = box.getPosition();
    float width = box.getWidth();
    float height = box.getHeight();
    float halfWidth = width / 2.0f;

    Vec2 position1 = new Vec2(position.x - halfWidth / 2.0f, position.y);
    Vec2 position2 = new Vec2(position.x + halfWidth / 2.0f, position.y);

    Box2D box1 = new Box2D(position1, halfWidth, height);
