import java.beans.Introspector;

public class StringUtils {
    /** 
     * Reverse of Introspector.decapitalize
     */
    public static String capitalize(String name) {
        if (name == null || name.length() == 0) {
            return name;
        }
        if (name.length() > 1 && Character.isUpperCase(name.charAt(1)) && Character.isLowerCase(name.charAt(0))) {
            return name;
        }
        char chars[] = name.toCharArray();
        chars[0] = Character.toUpperCase(chars[0]);
        return new String(chars);
    }

    public static void main(String[] args) {
        System.out.println(capitalize("string")); // Output: String
        System.out.println(capitalize("STRING")); // Output: STRING
        System.out.println(capitalize("sTRING")); // Output: STRING
        System.out.println(capitalize(""));       // Output: 
        System.out.println(capitalize(null));     // Output: null
    }
}
