import java.util.concurrent.locks.ReentrantLock;

class ListNodeImpl<E> {
    E item;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(ListNodeImpl<E> prev, E element, ListNodeImpl<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

class DoublyLinkedList<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private final ReentrantLock lock = new ReentrantLock();

    private void addListNode(ListNodeImpl<E> node) {
        lock.lock();
        try {
            if (last == null) {
                first = last = node;
            } else {
                last.next = node;
                node.prev = last;
                last = node;
            }
        } finally {
            lock.unlock();
        }
    }

    private void removeListNode(ListNodeImpl<E> node) {
        lock.lock();
        try {
            ListNodeImpl<E> next = node.next;
            ListNodeImpl<E> prev = node.prev;

            if (prev == null) {
                first = next;
            } else {
                prev.next = next;
                node.prev = null;
            }

            if (next == null) {
                last = prev;
            } else {
                next.prev = prev;
                node.next = null;
            }
        } finally {
            lock.unlock();
        }
    }

    private void moveAllListNodes(DoublyLinkedList<E> list) {
        lock.lock();
        list.lock.lock();
        try {
            ListNodeImpl<E> current = list.first;
            while (current != null) {
                ListNodeImpl<E> next = current.next;
                list.removeListNode(current);
                addListNode(current);
                current = next;
            }
        } finally {
            list.lock.unlock();
            lock.unlock();
        }
    }
}
